(function(root){
'use strict';
let active=null,serial=0;
function carSVG(color,accent,id,player=false){
 return `<svg viewBox="0 0 180 160" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="${id}paint" x1="0" y1="0" x2=".75" y2="1"><stop stop-color="${accent}"/><stop offset=".48" stop-color="${color}"/><stop offset="1" stop-color="#382059"/></linearGradient><linearGradient id="${id}glass" x2="0" y2="1"><stop stop-color="#e6ffff"/><stop offset="1" stop-color="#83c4e8"/></linearGradient><linearGradient id="${id}rubber" x2="0" y2="1"><stop stop-color="#55436f"/><stop offset=".5" stop-color="#1f1838"/><stop offset="1" stop-color="#514563"/></linearGradient></defs><ellipse cx="90" cy="140" rx="77" ry="15" fill="#17122f" opacity=".3"/><path d="M36 86 42 51q5-26 48-26t48 26l6 35" fill="url(#${id}paint)" stroke="#3d275f" stroke-width="3"/><path d="M56 62 60 47q29-22 60 0l4 15Z" fill="url(#${id}glass)" stroke="#4b306b" stroke-width="3"/><path d="m65 46 29-10M61 54l43-16" stroke="#fff" opacity=".65" stroke-width="5" stroke-linecap="round"/><path d="M31 81Q90 59 149 81l11 34q0 19-70 19t-70-19Z" fill="url(#${id}paint)" stroke="#3d275f" stroke-width="3"/><path d="M30 91q60-19 120 0" fill="none" stroke="${accent}" stroke-width="5" stroke-linecap="round"/><path d="M24 117q65 25 132 0v13q-66 25-132 0Z" fill="url(#${id}rubber)" stroke="#291f42" stroke-width="3"/><ellipse cx="46" cy="103" rx="11" ry="7" fill="#fff0ac"/><ellipse cx="134" cy="103" rx="11" ry="7" fill="#fff0ac"/><ellipse cx="43" cy="101" rx="5" ry="3" fill="#fff"/><ellipse cx="131" cy="101" rx="5" ry="3" fill="#fff"/><path d="M72 114q18 9 36 0" fill="none" stroke="#fff3dc" stroke-width="3.5" stroke-linecap="round"/><path d="M137 49V8q0-7 9-7" fill="none" stroke="#c5b8dd" stroke-width="3"/><path d="M138 12h7" stroke="#fff0ad" stroke-width="3"/>${player?'<circle cx="90" cy="82" r="14" fill="#ffcf5d" stroke="#fff2b2" stroke-width="2"/><path d="m90 72 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z" fill="#9c6323"/>':''}</svg>`;
}
function mount(container,q,onAnswer){
 dispose(); if(!container)throw new Error('CarRide precisa de um elemento de montagem.');
 const id='ride'+(++serial),opts=q.options.slice(0,4),timers=new Set();let lane=1,busy=false,won=false,disposed=false;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const later=(fn,ms)=>{const t=setTimeout(()=>{timers.delete(t);if(!disposed)fn();},ms);timers.add(t);};
 const colors=[['#f55376','#ffb1bd'],['#51a4d1','#b9edff'],['#8560dc','#d6bdff'],['#eca13c','#ffe49b']];
 container.innerHTML=`<section class="car-ride" aria-label="Pista de carros de trombada"><div class="car-ride__marquee"><span class="car-ride__spark">✦</span><span>Pista das estrelas</span><span class="car-ride__spark">✦</span></div><div class="car-ride__mission"><span>MISSÃO DO PILOTO</span><b>${q.a} ${q.op} ${q.b} = <strong class="car-ride__answer">?</strong></b><small>Dirija até o carro com a resposta e dê uma trombada!</small></div><div class="car-ride__arena"><div class="car-ride__light car-ride__light--left"></div><div class="car-ride__light car-ride__light--right"></div><div class="car-ride__bulbs">${Array.from({length:15},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div><div class="car-ride__floor"></div><div class="car-ride__lane-lines">${Array.from({length:3},(_,i)=>`<i style="left:${25+i*25}%"></i>`).join('')}</div><div class="car-ride__targets">${opts.map((n,i)=>`<button class="car-ride__target" style="--lane:${i};--car-glow:${colors[i][1]}" data-ride-lane="${i}" aria-label="Pista ${i+1}, carro com número ${n}" aria-pressed="${i===lane}"><span class="car-ride__number">${n}</span><span class="car-ride__target-body">${carSVG(...colors[i],id+'t'+i)}</span><span class="car-ride__target-ring"></span></button>`).join('')}</div><div class="car-ride__track-pointer" aria-hidden="true"></div><div class="car-ride__player" aria-hidden="true">${carSVG('#35bcae','#c7fff0',id+'p',true)}<div class="car-ride__speed-lines"><i></i><i></i><i></i></div><span class="car-ride__driver-tag">VOCÊ</span></div><div class="car-ride__impact" aria-hidden="true"><b>POW!</b>${Array.from({length:16},(_,i)=>`<i style="--angle:${i*22.5}deg;--distance:${70+(i%4)*22}px;--delay:${i%3*.035}s">${i%3?'★':'✦'}</i>`).join('')}</div><div class="car-ride__result" aria-live="polite"></div><div class="car-ride__rail"></div></div><div class="car-ride__dashboard"><div class="car-ride__steering"><button data-ride="left" aria-label="Dirigir para a pista à esquerda">◀</button><span class="car-ride__wheel" aria-hidden="true">◉<i></i></span><button data-ride="right" aria-label="Dirigir para a pista à direita">▶</button></div><button class="car-ride__accelerate" data-ride="go"><span aria-hidden="true">ϟ</span> Acelerar e trombar</button><div class="car-ride__speed"><span>PILOTO DAS ESTRELAS</span><div><i></i><i></i><i></i><i></i><i></i></div></div></div><p class="car-ride__instructions">Toque em um carro ou use ◀ ▶ para dirigir. Acelere com o botão ou Enter.</p><p class="car-ride__status sr-only" aria-live="polite"></p></section>`;
 const el=container.querySelector('.car-ride'),arena=el.querySelector('.car-ride__arena'),player=el.querySelector('.car-ride__player'),impact=el.querySelector('.car-ride__impact'),result=el.querySelector('.car-ride__result'),status=el.querySelector('.car-ride__status');
 function select(next,announce=true){if(busy||won||disposed)return;lane=Math.max(0,Math.min(3,next));el.style.setProperty('--selected-x',(12.5+25*lane)+'%');el.querySelectorAll('[data-ride-lane]').forEach((b,i)=>{b.classList.toggle('is-selected',i===lane);b.setAttribute('aria-pressed',String(i===lane));});el.querySelector('[data-ride="left"]').disabled=lane===0;el.querySelector('[data-ride="right"]').disabled=lane===3;el.querySelector('.car-ride__wheel').style.setProperty('--turn',((lane-1.5)*22)+'deg');if(announce)status.textContent=`Pista ${lane+1}: carro com número ${opts[lane]}.`;}
 function enable(){el.querySelectorAll('button').forEach(b=>b.disabled=false);select(lane,false);}
 function drive(){if(busy||won||disposed)return;busy=true;el.classList.remove('is-returning','is-wrong','is-hit');result.textContent='';el.querySelectorAll('button').forEach(b=>b.disabled=true);const target=el.querySelector('[data-ride-lane="'+lane+'"]'),distance=target.offsetTop+23-player.offsetTop;el.style.setProperty('--drive-y',distance+'px');el.classList.add('is-driving');status.textContent=`Acelerando na pista ${lane+1}!`;const value=opts[lane],correct=value===q.answer;
  later(()=>{el.classList.add('is-hit',correct?'is-winning':'is-wrong');impact.style.left=(12.5+25*lane)+'%';el.querySelector('[data-ride-lane="'+lane+'"]').classList.add('is-bumped');impact.querySelector('b').textContent=correct?'UAU!':'PLOFT!';result.textContent=correct?'Trombada certeira! ★':'Quase! Volte à pista e escolha outro carro.';if(correct){won=true;el.querySelector('.car-ride__answer').textContent=q.answer;}},reduced?100:680);
  later(()=>{if(correct){status.textContent=`Trombada certa! ${q.a} ${q.op} ${q.b} = ${q.answer}.`;onAnswer(value);}else{el.classList.remove('is-driving','is-hit');el.classList.add('is-returning');el.querySelectorAll('.is-bumped').forEach(x=>x.classList.remove('is-bumped'));onAnswer(value);later(()=>{busy=false;el.classList.remove('is-returning','is-wrong');enable();status.textContent='Escolha outra pista e acelere novamente.';},reduced?60:430);}},reduced?300:1320);
 }
 function click(e){const b=e.target.closest('button');if(!b||!el.contains(b))return;if(b.dataset.rideLane!==undefined)select(Number(b.dataset.rideLane));else if(b.dataset.ride==='left')select(lane-1);else if(b.dataset.ride==='right')select(lane+1);else if(b.dataset.ride==='go')drive();}
 function key(e){if(disposed||document.querySelector('.overlay')||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.key==='ArrowLeft'){e.preventDefault();select(lane-1);}else if(e.key==='ArrowRight'){e.preventDefault();select(lane+1);}else if(e.key==='ArrowUp'||e.key==='Enter'&&el.contains(e.target)){e.preventDefault();drive();}}
 let touchStart=null;function pointerDown(e){if(e.target.closest('button'))return;touchStart=e.clientX;}function pointerUp(e){if(touchStart===null)return;let delta=e.clientX-touchStart;touchStart=null;if(Math.abs(delta)>24)select(lane+(delta>0?1:-1));}
 el.addEventListener('click',click);document.addEventListener('keydown',key);arena.addEventListener('pointerdown',pointerDown);arena.addEventListener('pointerup',pointerUp);select(lane,false);
 active={dispose(){disposed=true;timers.forEach(clearTimeout);timers.clear();document.removeEventListener('keydown',key);el.removeEventListener('click',click);arena.removeEventListener('pointerdown',pointerDown);arena.removeEventListener('pointerup',pointerUp);}};
 return active;
}
function dispose(){if(active){active.dispose();active=null;}}
root.CarRide={mount,dispose};
})(window);
